            if (userInput.ToLower() == "quit")
            {
                Console.WriteLine("You quit the game");
                Thread.Sleep(1000);
                Environment.Exit(0);
            }
            else if (userInput.ToLower() == "proceed")
            {
                StartGame();
            }
            else if (userInput.ToLower() == "map")
            {
                Map();
            }
            else if (userInput.ToLower() == "inv")
            {
                InventoryMenu(ref tempHealth, tempMax);
                Thread.Sleep(1000);
